package dev.industrialtechnology.lighting;

import cpw.mods.fml.common.*;
import cpw.mods.fml.common.event.*;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import cpw.mods.fml.common.gameevent.TickEvent;
import cpw.mods.fml.relauncher.Side;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import net.minecraft.block.Block;
import net.minecraft.entity.player.*;
import net.minecraft.entity.item.EntityItem;
import net.minecraft.init.*;
import net.minecraft.inventory.*;
import net.minecraft.item.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.*;
import net.minecraft.world.*;
import net.minecraftforge.common.util.*;

@Mod(modid="industrialtech_colored_lamp_checks",name="Colored lamp checks",version="1",dependencies="required-after:industrialtech")
public final class ColoredLampChecks {
    private final List<String> report=new ArrayList<String>();private int phase,wait=25,failed;private WorldServer world;private FakePlayer player;
    @Mod.EventHandler public void init(FMLInitializationEvent e){if(!Boolean.getBoolean("industrialtech.colorLampTest"))return;if(e.getSide()==Side.CLIENT)dev.industrialtechnology.lighting.client.ColoredLampClientChecks.install();else FMLCommonHandler.instance().bus().register(this);}
    private static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    private void test(String name,Runnable r){try{r.run();report.add("PASS: "+name);}catch(Throwable t){failed++;report.add("FAIL: "+name+" :: "+t);t.printStackTrace();}}
    private static int x(int color){return 24+color*3;}
    private void craft(ItemStack expected,int[] slots,ItemStack[] ingredients){ContainerWorkbench table=new ContainerWorkbench(player.inventory,world,0,70,0);for(int i=0;i<slots.length;i++)table.craftMatrix.setInventorySlotContents(slots[i],ingredients[i]);Slot out=(Slot)table.inventorySlots.get(0);ItemStack found=out.getStack();check(found!=null&&found.getItem()==expected.getItem()&&found.getItemDamage()==expected.getItemDamage()&&found.stackSize==expected.stackSize,"Wrong global recipe output for "+expected+": "+found);ItemStack made=out.decrStackSize(expected.stackSize);out.onPickupFromSlot(player,made);for(int i=0;i<9;i++)check(table.craftMatrix.getStackInSlot(i)==null,"Craft did not consume exactly one input per occupied slot");}
    private void lever(int color){int x=x(color);player.inventory.mainInventory[0]=new ItemStack(Blocks.lever);player.inventory.currentItem=0;player.setPosition(x+.5,72,45.5);check(player.theItemInWorldManager.activateBlockOrUseItem(player,world,player.getHeldItem(),x,70,48,1,.5F,1,.5F),"Native lever placement failed for "+color);check(world.getBlock(x,71,48)==Blocks.lever,"Lever not attached");}
    private void toggle(int color){Blocks.lever.onBlockActivated(world,x(color),71,48,player,1,.5F,.5F,.5F);}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(e.phase!=TickEvent.Phase.END||phase==99||--wait>0)return;try{
        if(phase==0){world=MinecraftServer.getServer().worldServerForDimension(0);for(int cx=0;cx<8;cx++)for(int cz=0;cz<6;cz++)world.getChunkFromChunkCoords(cx,cz);player=new FakePlayer(world,new com.mojang.authlib.GameProfile(UUID.fromString("00000000-0000-0000-0000-000000001414"),"LampChecks")){public void addChatMessage(IChatComponent text){}public void sendPlayerAbilities(){}};player.playerNetServerHandler=new net.minecraft.network.NetHandlerPlayServer(MinecraftServer.getServer(),new net.minecraft.network.NetworkManager(false),player){public void sendPacket(net.minecraft.network.Packet packet){}};player.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);
            if("restart".equals(System.getProperty("industrialtech.colorLampPhase"))){test("Fresh JVM retains all 16 always-on colors and all redstone colors with their powered/off states",()->{for(int c=0;c<16;c++){check(world.getBlock(x(c),70,24)==ColoredLampRegistry.always&&world.getBlockMetadata(x(c),70,24)==c&&world.getBlock(x(c),70,24).getLightValue(world,x(c),70,24)==15,"Always-on save lost color/light "+c);boolean on=c==0||c==11||c==13;check(world.getBlock(x(c),70,48)==(on?ColoredLampRegistry.powered:ColoredLampRegistry.redstone)&&world.getBlockMetadata(x(c),70,48)==c,"Redstone save lost color/state "+c);}});finish();return;}
            test("All 64 lamp crafting/conversion/recolor recipes resolve through the real player workbench and consume exact ingredients",()->{for(int c=0;c<16;c++){ItemStack[] ingredients=new ItemStack[9];for(int i=0;i<9;i++)ingredients[i]=i==4?new ItemStack(Items.dye,1,15-c):new ItemStack((i&1)==0?Item.getItemFromBlock(Blocks.glass):Items.glowstone_dust);craft(new ItemStack(ColoredLampRegistry.always,4,c),new int[]{0,1,2,3,4,5,6,7,8},ingredients);craft(new ItemStack(ColoredLampRegistry.redstone,1,c),new int[]{0,1},new ItemStack[]{new ItemStack(ColoredLampRegistry.always,1,c),new ItemStack(Items.redstone)});for(Block b:new Block[]{ColoredLampRegistry.always,ColoredLampRegistry.redstone})craft(new ItemStack(b,1,c),new int[]{0,1},new ItemStack[]{new ItemStack(b,1,(c+5)&15),new ItemStack(Items.dye,1,15-c)});}});
            test("Every always-on color places in Survival with exact metadata and full native light, without a tile entity",()->{for(int c=0;c<16;c++){int x=x(c);world.setBlock(x,69,24,Blocks.stone,0,3);ItemStack stack=new ItemStack(ColoredLampRegistry.always,2,c);player.inventory.mainInventory[0]=stack;player.setPosition(x-2,72,22);check(stack.tryPlaceItemIntoWorld(player,world,x,69,24,1,.5F,1,.5F),"Color placement rejected "+c);check(stack.stackSize==1&&world.getBlock(x,70,24)==ColoredLampRegistry.always&&world.getBlockMetadata(x,70,24)==c,"Item color or count lost "+c);check(ColoredLampRegistry.always.getLightValue(world,x,70,24)==15&&world.getSavedLightValue(EnumSkyBlock.Block,x,70,24)==15,"Native light missing "+c);check(world.getTileEntity(x,70,24)==null&&!ColoredLampRegistry.always.hasTileEntity(c),"Lamp created a tile");}});
            test("All 16 redstone colors start dark, support an attached Survival lever, and keep their color when switched on",()->{for(int c=0;c<16;c++){int x=x(c);world.setBlock(x,70,48,ColoredLampRegistry.redstone,c,3);check(ColoredLampRegistry.redstone.getLightValue(world,x,70,48)==0,"Off lamp emits light "+c);lever(c);toggle(c);check(world.getBlock(x,70,48)==ColoredLampRegistry.powered&&world.getBlockMetadata(x,70,48)==c&&ColoredLampRegistry.powered.getLightValue(world,x,70,48)==15,"Switching lost color/light "+c);check(world.getBlock(x,71,48)==Blocks.lever,"Lever fell off powered lamp "+c);toggle(c);}});
            test("Always-on lamps remain lit when redstone power is added or removed",()->{int x=x(0);world.setBlock(x,69,24,Blocks.redstone_block,0,3);check(world.getBlock(x,70,24)==ColoredLampRegistry.always,"Power changed always-on type");world.setBlock(x,69,24,Blocks.stone,0,3);check(ColoredLampRegistry.always.getLightValue(world,x,70,24)==15,"Always-on lamp switched off");});
            test("Every lamp state retains full-cube collision and solid attachment faces",()->{for(Block b:new Block[]{ColoredLampRegistry.always,ColoredLampRegistry.redstone,ColoredLampRegistry.powered}){AxisAlignedBB box=b.getCollisionBoundingBoxFromPool(world,24,70,24);check(box.maxX-box.minX==1&&box.maxY-box.minY==1&&box.maxZ-box.minZ==1,"Lamp collision is not a full cube");for(ForgeDirection f:ForgeDirection.VALID_DIRECTIONS)check(b.isSideSolid(world,24,70,24,f),"Lamp face not solid: "+f);}});
            test("Breaking/picking lit lamps yields the unpowered item in the exact same color; hidden powered state has no item",()->{check(Item.getItemFromBlock(ColoredLampRegistry.powered)==null,"Powered state has a duplicate item");for(int c=0;c<16;c++){int x=x(c);world.setBlock(x,70,64,ColoredLampRegistry.powered,c,3);ArrayList<ItemStack> drops=ColoredLampRegistry.powered.getDrops(world,x,70,64,c,0);check(drops.size()==1&&drops.get(0).getItem()==Item.getItemFromBlock(ColoredLampRegistry.redstone)&&drops.get(0).getItemDamage()==c,"Wrong powered drop "+c);check(ColoredLampRegistry.powered.createStackedBlock(c).getItem()==Item.getItemFromBlock(ColoredLampRegistry.redstone),"Silk touch yields hidden state");ItemStack pick=ColoredLampRegistry.powered.getPickBlock(null,world,x,70,64);check(pick.getItemDamage()==c&&pick.getItem()==drops.get(0).getItem(),"Pick block loses color");world.setBlockToAir(x,70,64);}});
            toggle(11);phase=1;wait=8;return;
        }
        if(phase==1){test("Native delayed switch-off extinguishes all 16 colors without detaching levers; a renewed pulse stays on",()->{for(int c=0;c<16;c++){int x=x(c);check(world.getBlock(x,70,48)==(c==11?ColoredLampRegistry.powered:ColoredLampRegistry.redstone)&&world.getBlockMetadata(x,70,48)==c,"Delayed switch changed color/state "+c);check(world.getBlock(x,71,48)==Blocks.lever,"Delayed switch detached lever "+c);}});toggle(0);toggle(13);finish();}
    }catch(Throwable t){failed++;report.add("FAIL: fixture "+t);t.printStackTrace();finish();}}
    private void finish(){report.add("Failed: "+failed);try{Files.write(Paths.get("colored-lamps-"+System.getProperty("industrialtech.colorLampPhase","initial")+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}phase=99;MinecraftServer.getServer().initiateShutdown();}
}
